def getVideoDetails(**_extra):
    import json, os, datetime, hashlib, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0220000" if __import__("os").path.isdir("./environment_mix/0220000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getVideoDetails"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _stable_normalize(obj):
        if obj is None or isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_stable_normalize(x) for x in obj]
        if isinstance(obj, dict):
            return {k: _stable_normalize(obj[k]) for k in sorted(obj.keys())}
        return str(obj)

    def _request_key(params):
        payload = json.dumps({"tool_name": tool_name, "parameters": _stable_normalize(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()

    def _gen_ulidish(prefix):
        # Not a real ULID, but matches required pattern prefix_ + 26 Crockford-ish chars.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    raw_params = dict(_extra or {})
    rk = _request_key(raw_params)

    trs = _load("tool_requests.json")
    existing = next((r for r in trs if r.get("request_key") == rk), None)
    if existing and existing.get("status") == "succeeded":
        # Record invocation dynamics by updating updated_at
        existing["updated_at"] = now
        rs = existing.get("result_summary") or {}
        rs["cache_hit"] = True
        rs["reused_request"] = True
        existing["result_summary"] = rs
        _save("tool_requests.json", trs)
        return (existing.get("result_summary") or {}).get("result") or {"video": (existing.get("result_summary") or {}).get("video")}

    # Create/update request row to running
    if existing and existing.get("status") in ("received", "running", "failed"):
        req = existing
    else:
        req = {
            "id": _gen_ulidish("req"),
            "tool_name": tool_name,
            "raw_parameters": raw_params,
            "request_key": rk,
            "status": "received",
            "started_at": None,
            "completed_at": None,
            "error_message": None,
            "result_summary": None,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(req)

    # Transition: received -> running
    req["status"] = "running"
    req["started_at"] = req.get("started_at") or now
    req["updated_at"] = now
    _save("tool_requests.json", trs)

    def _finish_ok(result, summary):
        req["status"] = "succeeded"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["updated_at"] = req["completed_at"]
        req["error_message"] = None
        req["result_summary"] = summary
        latency_ms = int((time.time() - t0) * 1000)
        req["result_summary"]["latency_ms"] = latency_ms
        req["result_summary"]["result"] = result
        _save("tool_requests.json", trs)
        return result

    def _finish_err(code, msg, **x):
        req["status"] = "failed"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["updated_at"] = req["completed_at"]
        req["error_message"] = msg
        req["result_summary"] = {"latency_ms": int((time.time() - t0) * 1000)}
        _save("tool_requests.json", trs)
        return _err(code, msg, **x)

    # This vendor tool (as provided) has an empty parameter schema; accept missing inputs and return a safe cached response.
    # If the caller provided some identifier keys, we'll try to use them, but we won't require them.
    vid = raw_params.get("video_id") or raw_params.get("youtube_video_id") or raw_params.get("id")
    videos = _load("videos.json")
    channels = _load("channels.json")

    def _find_video_by_any(identifier):
        if not identifier or not isinstance(identifier, str):
            return None
        for v in videos:
            if v.get("youtube_video_id") == identifier or v.get("id") == identifier:
                return v
        return None

    if isinstance(vid, str) and vid.strip():
        v = _find_video_by_any(vid.strip())
        if not v:
            return _finish_err("NOT_FOUND", "Video not found in cache (offline datastore); cannot refresh from YouTube without upstream access.", video_id=vid)
        ch = next((c for c in channels if c.get("id") == v.get("channel_id")), None)
        result = {"video": v, "channel": ch}
        summary = {"video_id": v.get("id"), "youtube_video_id": v.get("youtube_video_id"), "cache_hit": True}
        return _finish_ok(result, summary)

    # No identifier provided: return a deterministic, non-error response with cached data (first active video).
    v = next((x for x in videos if x.get("status") in ("active", "unavailable")), None) or (videos[0] if videos else None)
    if not v:
        return _finish_ok({"video": None}, {"cache_hit": True, "note": "No videos in cache."})
    ch = next((c for c in channels if c.get("id") == v.get("channel_id")), None)
    return _finish_ok({"video": v, "channel": ch}, {"video_id": v.get("id"), "youtube_video_id": v.get("youtube_video_id"), "cache_hit": True, "defaulted": True})

