    trs = _load("tool_requests.json")
    existing = next((r for r in trs if r.get("request_key") == rk), None)
    if existing and existing.get("status") == "succeeded":
        existing["updated_at"] = now
        rs = existing.get("result_summary") or {}
        rs["cache_hit"] = True
        rs["reused_request"] = True
        existing["result_summary"] = rs
        _save("tool_requests.json", trs)
        return (existing.get("result_summary") or {}).get("result") or {"items": [], "page_info": {"total_results": 0, "results_per_page": 0}}

    if existing and existing.get("status") in ("received", "running", "failed"):
        req = existing
    else:
        req = {
            "id": _gen_ulidish("req"),
            "tool_name": tool_name,
            "raw_parameters": raw_params,
            "request_key": rk,
            "status": "received",
            "started_at": None,
            "completed_at": None,
            "error_message": None,
            "result_summary": None,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(req)

    req["status"] = "running"
    req["started_at"] = req.get("started_at") or now
    req["updated_at"] = now
    _save("tool_requests.json", trs)

    def _finish_ok(result, summary):
        req["status"] = "succeeded"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["updated_at"] = req["completed_at"]
        req["error_message"] = None
        req["result_summary"] = summary
        req["result_summary"]["latency_ms"] = int((time.time() - t0) * 1000)
        req["result_summary"]["result"] = result
        _save("tool_requests.json", trs)
        return result

    # Empty schema: accept empty args and treat as "list cached videos"
    q = raw_params.get("query") or raw_params.get("q")
    page_token = raw_params.get("page_token") or raw_params.get("pageToken")
    max_results = raw_params.get("max_results") or raw_params.get("maxResults") or 10
    try:
        max_results = int(max_results)
    except Exception:
        max_results = 10
    if max_results < 1:
        max_results = 1
    if max_results > 50:
        max_results = 50

    videos = _load("videos.json")
    channels = _load("channels.json")

    # Filter by query if provided
    items = []
    qn = q.strip().lower() if isinstance(q, str) and q.strip() else None
    for v in videos:
        if v.get("status") == "deleted":
            continue
        if qn:
            t = (v.get("title") or "").lower()
            d = (v.get("description") or "").lower()
            if qn not in t and qn not in d:
                continue
        ch = next((c for c in channels if c.get("id") == v.get("channel_id")), None)
        items.append({
            "id": v.get("youtube_video_id"),
            "video_row_id": v.get("id"),
            "title": v.get("title"),
            "description": v.get("description"),
            "published_at": v.get("published_at"),
            "thumbnail_url": v.get("thumbnail_url"),
            "channel": {"id": ch.get("youtube_channel_id") if ch else None, "title": ch.get("title") if ch else None},
        })

    # Deterministic "paging" via integer offset token
    offset = 0
    if isinstance(page_token, str) and page_token.strip():
        try:
            offset = int(page_token)
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(items)
    page = items[offset:offset + max_results]
    next_offset = offset + len(page)
    next_token = str(next_offset) if next_offset < total else None

    result = {
        "items": page,
        "page_info": {"total_results": total, "results_per_page": len(page)},
        "next_page_token": next_token,
        "prev_page_token": str(max(0, offset - max_results)) if offset > 0 else None,
    }
    return _finish_ok(result, {"total_results": total, "returned": len(page), "cache_hit": True})

