        }
        trs.append(req)
    req["status"] = "running"
    req["started_at"] = req.get("started_at") or now
    req["updated_at"] = now
    _save("tool_requests.json", trs)

    def _finish_ok(result, summary):
        req["status"] = "succeeded"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["updated_at"] = req["completed_at"]
        req["error_message"] = None
        req["result_summary"] = summary
        req["result_summary"]["latency_ms"] = int((time.time() - t0) * 1000)
        req["result_summary"]["result"] = result
        _save("tool_requests.json", trs)
        return result

    videos = _load("videos.json")
    transcripts = _load("transcripts.json")

    # Empty schema: accept missing args -> return transcripts for all cached videos (bounded)
    video_ids = raw_params.get("video_ids") or raw_params.get("youtube_video_ids") or raw_params.get("videos")
    resolved_video_rows = []

    def _resolve_video(identifier):
        if not identifier or not isinstance(identifier, str):
            return None
        for v in videos:
            if v.get("youtube_video_id") == identifier or v.get("id") == identifier:
                return v
        return None

    if isinstance(video_ids, list) and video_ids:
        for x in video_ids[:50]:
            v = _resolve_video(x)
            if v:
                resolved_video_rows.append(v)
            else:
                # include placeholder result even if missing
                resolved_video_rows.append({"id": None, "youtube_video_id": x})
    else:
        resolved_video_rows = [v for v in videos if v.get("status") != "deleted"][:50]

    results = []
    for v in resolved_video_rows:
        if not v.get("id"):
            results.append({
                "youtube_video_id": v.get("youtube_video_id"),
                "video_row_id": None,
                "transcripts": [],
                "status": "not_found",
            })
            continue

        trows = [t for t in transcripts if t.get("video_id") == v.get("id")]
        # If none exist, behave like cache miss but do not error (offline); return missing.
        if not trows:
            results.append({
                "youtube_video_id": v.get("youtube_video_id"),
                "video_row_id": v.get("id"),
                "transcripts": [],
                "status": "missing",
            })
            continue

        out_ts = []
        for t in trows:
            out_ts.append({
                "id": t.get("id"),
                "language": t.get("language"),
                "is_auto_generated": t.get("is_auto_generated"),
                "format": t.get("format"),
                "content_text": t.get("content_text"),
                "content_segments": t.get("content_segments"),
                "source": t.get("source"),
                "captured_at": t.get("captured_at"),
                "status": t.get("status"),
                "error_message": t.get("error_message"),
            })
        results.append({
            "youtube_video_id": v.get("youtube_video_id"),
            "video_row_id": v.get("id"),
            "transcripts": out_ts,
            "status": "ok",
        })

    return _finish_ok({"results": results}, {"returned_videos": len(results), "cache_hit": True})

