        return hashlib.sha256(payload.encode("utf-8")).hexdigest()

    def _gen_ulidish(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    raw_params = dict(_extra or {})
    rk = _request_key(raw_params)

    trs = _load("tool_requests.json")
    existing = next((r for r in trs if r.get("request_key") == rk), None)
    if existing and existing.get("status") == "succeeded":
        existing["updated_at"] = now
        rs = existing.get("result_summary") or {}
        rs["cache_hit"] = True
        rs["reused_request"] = True
        existing["result_summary"] = rs
        _save("tool_requests.json", trs)
        return (existing.get("result_summary") or {}).get("result") or {"items": [], "page_info": {"total_results": 0, "results_per_page": 0}}

    if existing and existing.get("status") in ("received", "running", "failed"):
        req = existing
    else:
        req = {
            "id": _gen_ulidish("req"),
            "tool_name": tool_name,
            "raw_parameters": raw_params,
            "request_key": rk,
            "status": "received",
            "started_at": None,
            "completed_at": None,
            "error_message": None,
            "result_summary": None,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(req)

    req["status"] = "running"
    req["started_at"] = req.get("started_at") or now
    req["updated_at"] = now
    _save("tool_requests.json", trs)

    def _finish_ok(result, summary):
        req["status"] = "succeeded"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["updated_at"] = req["completed_at"]
        req["error_message"] = None
        req["result_summary"] = summary
        req["result_summary"]["latency_ms"] = int((time.time() - t0) * 1000)
        req["result_summary"]["result"] = result
        _save("tool_requests.json", trs)
        return result

    videos = _load("videos.json")
    rels = _load("video_relationships.json")

    # Empty schema: accept missing args.
    seed = raw_params.get("video_id") or raw_params.get("youtube_video_id") or raw_params.get("seed_video_id")
    page_token = raw_params.get("page_token") or raw_params.get("pageToken")
    max_results = raw_params.get("max_results") or raw_params.get("maxResults") or 10
    try:
        max_results = int(max_results)
    except Exception:
        max_results = 10
    if max_results < 1:
        max_results = 1
    if max_results > 50:
        max_results = 50

    def _resolve_video(identifier):
        if not identifier or not isinstance(identifier, str):
            return None
        for v in videos:
            if v.get("youtube_video_id") == identifier or v.get("id") == identifier:
                return v
        return None

    seed_row = _resolve_video(seed) if isinstance(seed, str) and seed.strip() else None
    if not seed_row:
        # fall back to any seed that has related edges; else any video
        any_rel = next((r for r in rels if r.get("relation_type") == "related" and r.get("status") == "active"), None)
        if any_rel:
            seed_row = next((v for v in videos if v.get("id") == any_rel.get("source_video_id")), None)
        if not seed_row:
            seed_row = next((v for v in videos if v.get("status") in ("active", "unavailable")), None)

    if not seed_row:
        return _finish_ok({"seed_video": None, "items": [], "page_info": {"total_results": 0, "results_per_page": 0}}, {"cache_hit": True, "note": "No videos in cache."})

    # Collect active related edges; if none, return empty set (no error)
    edges = [r for r in rels if r.get("relation_type") == "related" and r.get("source_video_id") == seed_row.get("id") and r.get("status") == "active"]
    # Sort by captured_at desc then optional score desc then rank asc
    def _edge_key(r):
        dt = _parse_dt(r.get("captured_at")) or datetime.datetime.min
        score = r.get("score")
        score = float(score) if isinstance(score, (int, float)) else -1.0
        rank = r.get("rank")
        rank = int(rank) if isinstance(rank, int) else 10**9
        return (dt, score, -rank)

    edges.sort(key=_edge_key, reverse=True)

    offset = 0
    if isinstance(page_token, str) and page_token.strip():
        try:
            offset = int(page_token)
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(edges)
    page_edges = edges[offset:offset + max_results]
    targets = []
    for e in page_edges:
        tv = next((v for v in videos if v.get("id") == e.get("target_video_id")), None)
        if not tv:
            continue
        targets.append({
            "id": tv.get("youtube_video_id"),
            "video_row_id": tv.get("id"),
            "title": tv.get("title"),
            "published_at": tv.get("published_at"),
