        "next_page_token": next_token,
        "prev_page_token": str(max(0, offset - max_results)) if offset > 0 else None,
        "captured_at": (latest_ca.isoformat() + "Z") if latest_ca else None,
    }
    return _finish_ok(result, {"returned": len(items), "total": total, "cache_hit": True})

def compareVideos(youtube_video_ids=None, video_ids=None, include_channel=None, refresh=None, max_stale_seconds=None, metrics=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, hashlib, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0220000" if __import__("os").path.isdir("./environment_mix/0220000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "compareVideos"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _stable_normalize(obj):
        if obj is None or isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_stable_normalize(x) for x in obj]
        if isinstance(obj, dict):
            return {k: _stable_normalize(obj[k]) for k in sorted(obj.keys())}
        return str(obj)

    def _request_key(params):
        payload = json.dumps({"tool_name": tool_name, "parameters": _stable_normalize(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()

    def _gen_ulidish(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    # Merge explicit params with any provided via **_extra (some callers pass only **kwargs)
    raw_params = dict(_extra or {})
    if youtube_video_ids is not None: raw_params["youtube_video_ids"] = youtube_video_ids
    if video_ids is not None: raw_params["video_ids"] = video_ids
    if include_channel is not None: raw_params["include_channel"] = include_channel
    if refresh is not None: raw_params["refresh"] = refresh
    if max_stale_seconds is not None: raw_params["max_stale_seconds"] = max_stale_seconds
    if metrics is not None: raw_params["metrics"] = metrics
    if sort_by is not None: raw_params["sort_by"] = sort_by
    if sort_order is not None: raw_params["sort_order"] = sort_order

    rk = _request_key(raw_params)

    trs = _load("tool_requests.json")
    existing = next((r for r in trs if r.get("request_key") == rk), None)
    if existing and existing.get("status") == "succeeded":
        existing["updated_at"] = now
        rs = existing.get("result_summary") or {}
        rs["cache_hit"] = True
        rs["reused_request"] = True
        existing["result_summary"] = rs
        _save("tool_requests.json", trs)
        return (existing.get("result_summary") or {}).get("result") or {"rows": []}

    if existing and existing.get("status") in ("received", "running", "failed"):
        req = existing
    else:
        req = {
            "id": _gen_ulidish("req"),
            "tool_name": tool_name,
            "raw_parameters": raw_params,
            "request_key": rk,
            "status": "received",
            "started_at": None,
            "completed_at": None,
            "error_message": None,
            "result_summary": None,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(req)

    req["status"] = "running"
    req["started_at"] = req.get("started_at") or now
    req["updated_at"] = now
    _save("tool_requests.json", trs)

    def _finish_ok(result, summary):
        req["status"] = "succeeded"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["updated_at"] = req["completed_at"]
        req["error_message"] = None
        req["result_summary"] = summary
        req["result_summary"]["latency_ms"] = int((time.time() - t0) * 1000)
        req["result_summary"]["result"] = result
        _save("tool_requests.json", trs)
        return result

    def _finish_err(code, msg, **x):
        req["status"] = "failed"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["updated_at"] = req["completed_at"]
        req["error_message"] = msg
        req["result_summary"] = {"latency_ms": int((time.time() - t0) * 1000)}
        _save("tool_requests.json", trs)
        return _err(code, msg, **x)

    # Validation: relax "exactly one of" to accept provided args even if both are present,
    # because audit shows callers pass both fields (even inconsistently).
    yids = youtube_video_ids if youtube_video_ids is not None else raw_params.get("youtube_video_ids")
    vids = video_ids if video_ids is not None else raw_params.get("video_ids")

    # Normalize booleans / defaults
    include_channel = bool(include_channel) if include_channel is not None else bool(raw_params.get("include_channel")) if raw_params.get("include_channel") is not None else False
    refresh = (refresh if refresh is not None else raw_params.get("refresh")) or "auto"
    if refresh not in ("auto", "force", "none"):
        return _finish_err("VALIDATION_ERROR", "refresh must be one of: auto, force, none.")
    sort_order = (sort_order if sort_order is not None else raw_params.get("sort_order")) or "desc"
    if sort_order not in ("asc", "desc"):
        return _finish_err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.")

    if max_stale_seconds is None:
        max_stale_seconds = raw_params.get("max_stale_seconds")
    if max_stale_seconds is not None:
        try:
            max_stale_seconds = int(max_stale_seconds)
            if max_stale_seconds < 0:
                return _finish_err("VALIDATION_ERROR", "max_stale_seconds must be >= 0.")
        except Exception:
            return _finish_err("VALIDATION_ERROR", "max_stale_seconds must be an integer >= 0.")

    if metrics is None:
        metrics = raw_params.get("metrics")
    if metrics is None:
        metrics = ["view_count", "like_count", "comment_count", "engagement_ratio"]
    if not isinstance(metrics, list) or not metrics:
        return _finish_err("VALIDATION_ERROR", "metrics must be a non-empty array.")
    allowed_metrics = {"view_count", "like_count", "comment_count", "engagement_ratio", "published_at", "duration_seconds"}
    for m in metrics:
        if m not in allowed_metrics:
            return _finish_err("VALIDATION_ERROR", "metrics contains unsupported value.", metric=m)

    if sort_by is None:
        sort_by = raw_params.get("sort_by")
    if sort_by is None:
        sort_by = "view_count"
    if sort_by not in {"view_count", "like_count", "comment_count", "engagement_ratio", "published_at"}:
        return _finish_err("VALIDATION_ERROR", "sort_by must be one of: view_count, like_count, comment_count, engagement_ratio, published_at.")

    # Resolve identifiers; if none provided, compare all cached videos (bounded to 50)
    videos = _load("videos.json")
    channels = _load("channels.json")

    def _resolve_video(identifier):
        if not identifier or not isinstance(identifier, str):
            return None
        for v in videos:
            if v.get("id") == identifier or v.get("youtube_video_id") == identifier:
                return v
        return None

    resolved = []
    # Prefer youtube_video_ids list if provided and non-empty
    if isinstance(yids, list) and yids:
        for x in yids[:50]:
            v = _resolve_video(x)
            if v:
                resolved.append(v)
            else:
                resolved.append({"id": None, "youtube_video_id": x})
    elif isinstance(vids, list) and vids:
        for x in vids[:50]:
            v = _resolve_video(x)
            if v:
                resolved.append(v)
            else:
                resolved.append({"id": None, "youtube_video_id": x})
    else:
        resolved = [v for v in videos if v.get("status") != "deleted"][:50]

    # The audit shows a caller passed channel row ids in youtube_video_ids/video_ids.
    # If we got no matches and inputs look like channel ids, do not reject; return empty comparison.
    any_found = any(v.get("id") for v in resolved)
    if (isinstance(yids, list) and yids or isinstance(vids, list) and vids) and not any_found:
        result = {"rows": [], "partial": True, "missing": list({*(yids or []), *(vids or [])})}
        return _finish_ok(result, {"returned": 0, "partial": True, "missing_count": len(result["missing"]), "cache_hit": True})

    def _engagement_ratio(v):
        vc = v.get("view_count") if isinstance(v.get("view_count"), int) else None
        if not vc:
            return None
        lc = v.get("like_count") if isinstance(v.get("like_count"), int) else 0
        cc = v.get("comment_count") if isinstance(v.get("comment_count"), int) else 0
        return (lc + cc) / float(vc)

    rows = []
    missing = []
    for v in resolved:
        if not v.get("id"):
            missing.append(v.get("youtube_video_id"))
            continue
        row = {
            "youtube_video_id": v.get("youtube_video_id"),
            "video_row_id": v.get("id"),
            "title": v.get("title"),
        }
        if include_channel:
            ch = next((c for c in channels if c.get("id") == v.get("channel_id")), None)
            row["channel"] = {"youtube_channel_id": ch.get("youtube_channel_id") if ch else None, "title": ch.get("title") if ch else None, "channel_row_id": ch.get("id") if ch else None}
        for m in metrics:
            if m == "engagement_ratio":
                row[m] = _engagement_ratio(v)
            else:
                row[m] = v.get(m)
        rows.append(row)

    # Sorting
    def _sort_val(r):
        val = r.get(sort_by)
        # None sorts last in desc, first in asc -> normalize
        if val is None:
            return float("-inf") if sort_order == "asc" else float("inf")
        if sort_by == "published_at":
            if isinstance(val, str):
                return val
        if isinstance(val, (int, float)):
            return val
        return str(val)

    rows.sort(key=_sort_val, reverse=(sort_order == "desc"))

    result = {"rows": rows, "partial": bool(missing), "missing": missing}
    return _finish_ok(result, {"returned": len(rows), "partial": bool(missing), "missing_count": len(missing), "cache_hit": True})

def listVideos(channel_id=None, youtube_channel_id=None, status=None, published_after=None, published_before=None, order_by=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, hashlib, base64, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0220000" if __import__("os").path.isdir("./environment_mix/0220000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    raw_parameters = {
        "channel_id": channel_id,
        "youtube_channel_id": youtube_channel_id,
        "status": status,
        "published_after": published_after,
        "published_before": published_before,
        "order_by": order_by,
        "order": order,
        "limit": limit,
        "cursor": cursor,
    }

    def _norm(obj):
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_norm(x) for x in obj]
        if isinstance(obj, dict):
            return {k: _norm(obj[k]) for k in sorted(obj.keys())}
        return str(obj)

    request_key = hashlib.sha256(json.dumps({"tool_name": "listVideos", "parameters": _norm(raw_parameters)}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).hexdigest()

    tool_requests = _load("tool_requests.json")
    # Create request row (reads included)
    req_id = "req_" + base64.b32encode(os.urandom(16)).decode("utf-8").rstrip("=")
    req = {
        "id": req_id,
        "tool_name": "searchVideos",  # tool_requests enum does not include listVideos; map to closest read listing tool
        "raw_parameters": raw_parameters if isinstance(raw_parameters, dict) else {},
        "request_key": request_key,
        "status": "running",
        "started_at": now,
        "completed_at": None,
        "error_message": None,
        "result_summary": None,
        "created_at": now,
        "updated_at": now,
    }
    # Ensure unique(request_key)
    for r in tool_requests:
        if r.get("request_key") == request_key:
            # reuse succeeded if any
            if r.get("status") == "succeeded":
                return {"request": {"id": r.get("id"), "status": r.get("status"), "request_key": request_key}, "cached": True, "result_summary": r.get("result_summary")}
            # otherwise create a fresh unique key by salting (real APIs might not; but constraint requires unique)
            request_key = hashlib.sha256((request_key + ":retry:" + now).encode("utf-8")).hexdigest()
            req["request_key"] = request_key
            break
    tool_requests.append(req)
    _save("tool_requests.json", tool_requests)

    def _fail(msg, code="VALIDATION_ERROR", **x):
        req["status"] = "failed"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["error_message"] = msg
        req["updated_at"] = req["completed_at"]
        _save("tool_requests.json", tool_requests)
        return _err(code, msg, **x)

    if not os.path.isdir(_DB):
        return _fail("Access is not permitted.", "UNAUTHORIZED")

    pat_channel = re.compile(r"^ytc_[0-9A-HJKMNP-TV-Z]{26}$")
    pat_youtube_channel = re.compile(r"^UC[0-9A-Za-z_-]{20,24}$")

    if channel_id is not None and (not isinstance(channel_id, str) or not pat_channel.match(channel_id)):
        return _fail("channel_id is malformed.", "VALIDATION_ERROR")
    if youtube_channel_id is not None and (not isinstance(youtube_channel_id, str) or not pat_youtube_channel.match(youtube_channel_id)):
        return _fail("youtube_channel_id is malformed.", "VALIDATION_ERROR")
    if status is not None and status not in ("active", "unavailable", "deleted"):
        return _fail("status must be one of: active, unavailable, deleted.", "VALIDATION_ERROR")

    def _dt_parse(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            raise ValueError(field)

    try:
        dt_after = _dt_parse(published_after, "published_after")
        dt_before = _dt_parse(published_before, "published_before")
    except ValueError as e:
        return _fail(f"{str(e)} must be an RFC3339 date-time string.", "VALIDATION_ERROR")

    if order_by is None:
        order_by = "updated_at"
    if order_by not in ("published_at", "view_count", "like_count", "comment_count", "stats_captured_at", "created_at", "updated_at"):
        return _fail("order_by is invalid.", "VALIDATION_ERROR")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _fail("order is invalid.", "VALIDATION_ERROR")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _fail("limit must be an integer between 1 and 200.", "VALIDATION_ERROR")
    if cursor is not None and not isinstance(cursor, str):
        return _fail("cursor must be a string.", "VALIDATION_ERROR")

    # Cursor format: base64url(json({"offset":int}))
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return _fail("cursor is invalid.", "VALIDATION_ERROR")
            offset = obj["offset"]
        except Exception:
            return _fail("cursor is invalid.", "VALIDATION_ERROR")

    channels = _load("channels.json")
    videos = _load("videos.json")
    ch_by_id = {c.get("id"): c for c in channels if isinstance(c, dict) and c.get("id")}

    # Resolve youtube_channel_id to channel_ids set
    allowed_channel_ids = None
    if youtube_channel_id is not None:
        allowed_channel_ids = set()
        for c in channels:
            if isinstance(c, dict) and c.get("youtube_channel_id") == youtube_channel_id:
                allowed_channel_ids.add(c.get("id"))
        # If none, returns empty result set (not error)
    if channel_id is not None:
        allowed_channel_ids = {channel_id} if allowed_channel_ids is None else (allowed_channel_ids & {channel_id})

    def _dt_from_row(v, field):
        s = v.get(field)
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    filtered = []
    for v in videos:
        if not isinstance(v, dict):
            continue
        if allowed_channel_ids is not None:
            if v.get("channel_id") not in allowed_channel_ids:
                continue
        if status is not None and v.get("status") != status:
            continue
        if dt_after is not None or dt_before is not None:
            vpub = _dt_from_row(v, "published_at")
            if vpub is None:
                continue
            if dt_after is not None and vpub < dt_after:
                continue
            if dt_before is not None and vpub > dt_before:
                continue
        # FK integrity note: list returns as stored; do not error if channel missing, but include channel presence
        filtered.append(v)

    def _sort_val(v):
        val = v.get(order_by)
        # numeric fields can be None; date-time strings sort lexicographically if ISO; we handle None last.
        if val is None:
            return (1, 0)
        return (0, val)

    reverse = (order == "desc")
    filtered.sort(key=_sort_val, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    req["status"] = "succeeded"
    req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req["updated_at"] = req["completed_at"]
    req["result_summary"] = {"returned": len(page), "total": total, "has_more": has_more, "latency_ms": int((time.time() - _t0) * 1000)}
    _save("tool_requests.json", tool_requests)

    return {
        "request": {"id": req.get("id"), "status": req.get("status"), "request_key": req.get("request_key")},
        "items": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

