        return _fail("limit must be an integer between 1 and 200.", "VALIDATION_ERROR")
    if cursor is not None and not isinstance(cursor, str):
        return _fail("cursor must be a string.", "VALIDATION_ERROR")

    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return _fail("cursor is invalid.", "VALIDATION_ERROR")
            offset = obj["offset"]
        except Exception:
            return _fail("cursor is invalid.", "VALIDATION_ERROR")

    channels = _load("channels.json")

    filtered = []
    for c in channels:
        if not isinstance(c, dict):
            continue
        if status is not None and c.get("status") != status:
            continue
        if country is not None:
            if c.get("country") != country:
                continue
        if q_norm is not None:
            title = (c.get("title") or "")
            custom = (c.get("custom_url") or "")
            hay = (str(title) + " " + str(custom)).lower()
            if q_norm not in hay:
                continue
        filtered.append(c)

    def _sort_val(c):
        val = c.get(order_by)
        if val is None:
            return (1, 0)
        return (0, val)

    reverse = (order == "desc")
    filtered.sort(key=_sort_val, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    req["status"] = "succeeded"
    req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req["updated_at"] = req["completed_at"]
    req["result_summary"] = {"returned": len(page), "total": total, "has_more": has_more, "latency_ms": int((time.time() - _t0) * 1000)}
    _save("tool_requests.json", tool_requests)

    return {
        "request": {"id": req.get("id"), "status": req.get("status"), "request_key": req.get("request_key")},
        "items": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def getVideoById(video_id, **_extra):
    import json, os, datetime, hashlib, base64, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0220000" if __import__("os").path.isdir("./environment_mix/0220000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    raw_parameters = {"video_id": video_id}

    request_key = hashlib.sha256(json.dumps({"tool_name": "getVideoById", "parameters": raw_parameters}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).hexdigest()

    tool_requests = _load("tool_requests.json")
    req_id = "req_" + base64.b32encode(os.urandom(16)).decode("utf-8").rstrip("=")
    req = {
        "id": req_id,
        "tool_name": "getVideoDetails",  # closest enum tool for single-video read
        "raw_parameters": raw_parameters,
        "request_key": request_key,
        "status": "running",
        "started_at": now,
        "completed_at": None,
        "error_message": None,
        "result_summary": None,
        "created_at": now,
        "updated_at": now,
    }
    # enforce unique(request_key)
    for r in tool_requests:
        if r.get("request_key") == request_key:
            if r.get("status") == "succeeded":
                # cannot return prior full record (not stored); proceed with fresh read but new key
                request_key = hashlib.sha256((request_key + ":retry:" + now).encode("utf-8")).hexdigest()
                req["request_key"] = request_key
            else:
                request_key = hashlib.sha256((request_key + ":retry:" + now).encode("utf-8")).hexdigest()
                req["request_key"] = request_key
            break
    tool_requests.append(req)
    _save("tool_requests.json", tool_requests)

    def _fail(msg, code="VALIDATION_ERROR", **x):
        req["status"] = "failed"
        req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req["error_message"] = msg
        req["updated_at"] = req["completed_at"]
        _save("tool_requests.json", tool_requests)
        return _err(code, msg, **x)

    if not os.path.isdir(_DB):
        return _fail("Access is not permitted.", "UNAUTHORIZED")

    pat = re.compile(r"^ytv_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(video_id, str) or not pat.match(video_id):
        return _fail("video_id is malformed.", "VALIDATION_ERROR")

    videos = _load("videos.json")
    found = None
    for v in videos:
        if isinstance(v, dict) and v.get("id") == video_id:
            found = v
            break
    if found is None:
        return _fail("Video not found.", "NOT_FOUND", video_id=video_id)

    req["status"] = "succeeded"
    req["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req["updated_at"] = req["completed_at"]
    req["result_summary"] = {"video_id": video_id, "latency_ms": int((time.time() - _t0) * 1000)}
    _save("tool_requests.json", tool_requests)

    return {
        "request": {"id": req.get("id"), "status": req.get("status"), "request_key": req.get("request_key")},
        "video": found,
    }

def updateVideoStatus(video_id, status, reason=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0220000" if __import__("os").path.isdir("./environment_mix/0220000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / idempotency key ----
    def _norm_params():
        return {"video_id": video_id, "status": status, "reason": reason}
    def _stable(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    _raw_params = _norm_params()
    _request_key = hashlib.sha256(("updateVideoStatus|" + _stable(_raw_params)).encode("utf-8")).hexdigest()

    tool_requests = _load("tool_requests.json")

    # Tool name enum in schema doesn't include these update* tools; still must log every call.
    def _append_request_row(req_status, started_at=None, completed_at=None, error_message=None, result_summary=None):
        req_id = "trq_" + hashlib.sha256((str(time.time_ns()) + _request_key).encode("utf-8")).hexdigest()[:26].upper()
        row = {
            "id": req_id,
            "tool_name": "updateVideoStatus",
            "raw_parameters": _raw_params,
            "request_key": _request_key,
            "status": req_status,
            "started_at": started_at,
            "completed_at": completed_at,
            "error_message": error_message,
            "result_summary": result_summary,
            "created_at": _now,
            "updated_at": _now,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    # If prior succeeded request exists, return same result snapshot (idempotent)
    prior = None
    for r in tool_requests:
        if r.get("request_key") == _request_key:
            prior = r
            break
    if prior and prior.get("status") == "succeeded":
        # Return a stable envelope. We cannot fabricate a row; re-read current row.
        videos = _load("videos.json")
        v = next((x for x in videos if x.get("id") == video_id), None)
        # If the row vanished, surface NOT_FOUND (no success without effect).
        if not v:
            return _err("NOT_FOUND", "Video not found.", video_id=video_id)
        return {
            "request": {"id": prior.get("id"), "request_key": _request_key, "status": "succeeded"},
            "video": v,
        }

    req_row = _append_request_row("received", started_at=None, completed_at=None)

    # ---- validation ----
    if not isinstance(video_id, str):
        _append_request_row("failed", started_at=_now, completed_at=_now, error_message="video_id must be a string.")
        return _err("VALIDATION_ERROR", "video_id must be a string.", field="video_id")
    if not re.match(r"^ytv_[0-9A-HJKMNP-TV-Z]{26}$", video_id):
        _append_request_row("failed", started_at=_now, completed_at=_now, error_message="video_id format is invalid.")
        return _err("VALIDATION_ERROR", "video_id format is invalid.", field="video_id")
    if status not in ("active", "unavailable", "deleted"):
        _append_request_row("failed", started_at=_now, completed_at=_now, error_message="status is invalid.")
        return _err("VALIDATION_ERROR", "status is invalid.", field="status")
    if reason is not None:
        if not isinstance(reason, str):
            _append_request_row("failed", started_at=_now, completed_at=_now, error_message="reason must be a string.")
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
        if len(reason) > 500:
            _append_request_row("failed", started_at=_now, completed_at=_now, error_message="reason exceeds max length.")
            return _err("VALIDATION_ERROR", "reason exceeds maxLength=500.", field="reason")

    # ---- ambient auth resolution ----
    # No explicit credentials in schema. Per contract, if signature carries no auth parameter, must not refuse a well-formed request.
    # We still keep the UNAUTHORIZED code reserved; only return if datastore indicates no callable context at all.
    # This service has no auth collections, so always authorized.
    authorized = True
    if not authorized:
        _append_request_row("failed", started_at=_now, completed_at=_now, error_message="Unauthorized.")
        return _err("UNAUTHORIZED", "Unauthorized.")

    # mark running
    req_row["status"] = "running"
    req_row["started_at"] = _now
    req_row["updated_at"] = _now
    _save("tool_requests.json", tool_requests)

    # ---- mutation ----
    videos = _load("videos.json")
    idx = None
    for i, x in enumerate(videos):
        if x.get("id") == video_id:
            idx = i
            break
    if idx is None:
        req_row["status"] = "failed"
        req_row["completed_at"] = _now
        req_row["error_message"] = "Video not found."
        req_row["updated_at"] = _now
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Video not found.", video_id=video_id)

    video = videos[idx]
    cur = video.get("status")
    allowed = {
        "active": {"unavailable", "deleted"},
        "unavailable": {"active", "deleted"},
        "deleted": set(),
    }
    if cur not in allowed:
        req_row["status"] = "failed"
        req_row["completed_at"] = _now
        req_row["error_message"] = "Current video status is invalid."
        req_row["updated_at"] = _now
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "Current video status is invalid.", current_status=cur)

    if status == cur:
        # idempotent no-op is allowed only if it "matched"; return the row without claiming mutation count
        req_row["status"] = "succeeded"
        req_row["completed_at"] = _now
        req_row["result_summary"] = {"video_id": video_id, "updated": False, "reason_recorded": bool(reason)}
        req_row["updated_at"] = _now
        _save("tool_requests.json", tool_requests)
        return {"request": {"id": req_row["id"], "request_key": _request_key, "status": "succeeded"}, "video": video}

    if status not in allowed[cur]:
        req_row["status"] = "failed"
        req_row["completed_at"] = _now
        req_row["error_message"] = "Illegal status transition."
        req_row["updated_at"] = _now
        _save("tool_requests.json", tool_requests)
        return _err(
            "VALIDATION_ERROR",
            "Illegal status transition.",
            from_status=cur,
            to_status=status,
            allowed_transitions=sorted(list(allowed[cur])),
        )

    video["status"] = status
    video["updated_at"] = _now
    videos[idx] = video
    _save("videos.json", videos)

    req_row["status"] = "succeeded"
    req_row["completed_at"] = _now
    req_row["result_summary"] = {
        "video_id": video_id,
        "updated": True,
        "from_status": cur,
        "to_status": status,
        "reason_recorded": bool(reason),
        "latency_ms": int((time.time() - _t0) * 1000),
    }
    req_row["updated_at"] = _now
    _save("tool_requests.json", tool_requests)

    return {"request": {"id": req_row["id"], "request_key": _request_key, "status": "succeeded"}, "video": video}

